const messageEditorBrowser = GetCurrentEditorElement();
messageEditorBrowser.addEventListener(
  "DoZoomEnlarge",
  () => {
    ZoomManager.scrollZoomEnlarge(messageEditorBrowser);
  },
  true
);
messageEditorBrowser.addEventListener(
  "DoZoomReduce",
  () => {
    ZoomManager.scrollReduceEnlarge(messageEditorBrowser);
  },
  true
);
